"""Timeline-driven regional shape-key animation for GEEHUB Blender scenes.

The timeline's semantic stages are converted into continuous, interpolated shape-key
curves. This module deliberately operates on the unified rig mesh, not the old
independent-ellipsoid blockout.
"""
from __future__ import annotations

import math
import bpy
from mathutils import Vector

# Local-space envelopes fit the neutral humanoid generated by rigged_character.py.
# Each region expands smoothly around its own anatomical centre.
REGIONS = {
    "pectorals": ((0.0, -0.02, 2.28), (1.02, 0.76, 0.60), (1.22, 1.20, 1.12)),
    "deltoids": ((0.0, 0.0, 2.60), (1.22, 0.82, 0.66), (1.16, 1.14, 1.14)),
    "traps": ((0.0, 0.02, 2.76), (0.76, 0.62, 0.42), (1.15, 1.12, 1.13)),
    "arms": ((0.0, 0.0, 1.93), (1.34, 0.72, 1.12), (1.18, 1.16, 1.16)),
    "lats": ((0.0, 0.08, 2.05), (1.08, 0.72, 0.86), (1.20, 1.18, 1.12)),
    "back": ((0.0, 0.18, 2.10), (1.10, 0.68, 0.94), (1.17, 1.18, 1.13)),
    "torso": ((0.0, 0.02, 1.93), (0.82, 0.62, 1.08), (1.14, 1.12, 1.13)),
    "quadriceps": ((0.0, 0.0, 0.58), (0.72, 0.70, 0.92), (1.17, 1.15, 1.16)),
    "calves": ((0.0, 0.0, -0.43), (0.68, 0.66, 0.72), (1.14, 1.13, 1.15)),
    "whole_body": ((0.0, 0.0, 1.20), (1.65, 1.0, 2.45), (1.08, 1.08, 1.10)),
}
STAGE_LEVEL = {
    "onset": 0.14,
    "early-growth": 0.40,
    "main-growth": 0.82,
    "escalation": 1.0,
    "terminal": 1.0,
}


def _make_region_key(mesh, name, centre, radius, factors):
    keys = mesh.shape_key_add(name="Basis", from_mix=False) if mesh.data.shape_keys is None else mesh.data.shape_keys.key_blocks[0]
    key = mesh.shape_key_add(name="GROWTH / " + name, from_mix=False)
    c, r, f = Vector(centre), Vector(radius), Vector(factors)
    for source, point in zip(mesh.data.vertices, key.data):
        p = source.co
        delta = p - c
        q = (delta.x / r.x) ** 2 + (delta.y / r.y) ** 2 + (delta.z / r.z) ** 2
        weight = math.exp(-2.4 * q)
        target = c + Vector((delta.x * f.x, delta.y * f.y, delta.z * f.z))
        point.co = p.lerp(target, weight)
    return key


def animate_timeline_growth(mesh, timeline):
    """Create symmetric regional shape keys and animate them from semantic stages."""
    if not timeline or not timeline.get("stages"):
        raise ValueError("A timeline with stages is required")
    scene = bpy.context.scene
    fps = int(timeline.get("timebase", {}).get("fps", scene.render.fps))
    scene.render.fps = fps
    scene.frame_start = 1
    scene.frame_end = int(round(float(timeline["duration_seconds"]) * fps))
    shape_keys = {}
    for region, (centre, radius, factors) in REGIONS.items():
        shape_keys[region] = _make_region_key(mesh, region, centre, radius, factors)

    current = {region: 0.0 for region in REGIONS}
    for stage in timeline["stages"]:
        start = max(1, int(round(float(stage["start_seconds"]) * fps)) + 1)
        end = max(start + 1, int(round(float(stage["end_seconds"]) * fps)))
        growth = stage.get("growth", {})
        active = set(growth.get("regions", []))
        if growth.get("active"):
            level = STAGE_LEVEL.get(stage["id"], 0.5)
            for region in REGIONS:
                aliases = {
                    "pectorals": {"chest", "pectorals"},
                    "deltoids": {"deltoids", "shoulders"},
                    "traps": {"traps"},
                    "arms": {"arms", "biceps", "triceps", "forearms"},
                    "lats": {"lats"},
                    "back": {"back"},
                    "torso": {"torso", "whole body"},
                    "quadriceps": {"quadriceps", "thighs", "legs"},
                    "calves": {"calves", "legs"},
                    "whole_body": {"whole body", "height", "limb proportions"},
                }[region]
                if active.intersection(aliases):
                    target = max(current[region], level)
                    key = shape_keys[region]
                    key.value = current[region]
                    key.keyframe_insert(data_path="value", frame=start)
                    key.value = target
                    key.keyframe_insert(data_path="value", frame=end)
                    current[region] = target

    # A continuous eased curve; no stage boundary resets the accumulated state.
    for key in shape_keys.values():
        if key.id_data.animation_data and key.id_data.animation_data.action:
            for curve in key.id_data.animation_data.action.fcurves:
                for point in curve.keyframe_points:
                    point.interpolation = "BEZIER"
                    point.handle_left_type = "AUTO_CLAMPED"
                    point.handle_right_type = "AUTO_CLAMPED"
    return shape_keys


def animate_timeline_camera(camera, timeline, target=(0.0, 0.0, 1.25)):
    """Key a restrained continuous orbit/push/pull from timeline stage boundaries."""
    stages = timeline["stages"]
    fps = int(timeline.get("timebase", {}).get("fps", 24))
    total = int(round(float(timeline["duration_seconds"]) * fps))
    # A shallow arc keeps the subject readable while revealing changing silhouette.
    count = max(1, len(stages) - 1)
    for index, stage in enumerate(stages):
        frame = max(1, int(round(float(stage["start_seconds"]) * fps)) + 1)
        phase = index / count
        angle = -0.12 + phase * 0.34
        radius = 9.0 - 0.55 * min(1.0, phase * 1.4)
        camera.location = (math.sin(angle) * radius, -math.cos(angle) * radius, 2.35 - 0.35 * phase)
        camera.rotation_euler = (Vector(target) - camera.location).to_track_quat("-Z", "Y").to_euler()
        camera.keyframe_insert(data_path="location", frame=frame)
        camera.keyframe_insert(data_path="rotation_euler", frame=frame)
    camera.keyframe_insert(data_path="location", frame=total)
    camera.keyframe_insert(data_path="rotation_euler", frame=total)
    if camera.animation_data and camera.animation_data.action:
        for curve in camera.animation_data.action.fcurves:
            for point in curve.keyframe_points:
                point.interpolation = "BEZIER"
                point.handle_left_type = "AUTO_CLAMPED"
                point.handle_right_type = "AUTO_CLAMPED"
